INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(9001, '2 Kings 2:10', '2 Kings', 2, 10, '&nbsp;الياس ورته وفرمائيل، ”تا يو مشکل څيز غوښتے دے، خو چې کله زۀ ستا نه جدا کړے شم او تۀ مې په ختلو ووينې نو دا به تا ته مِلاو شى، خو کۀ تۀ مې ونۀ وينې، نو دا به تا ته نۀ ملاويږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9002, '2 Kings 2:11', '2 Kings', 2, 11, '&nbsp;کله چې هغوئ روان وُو او خبرې يې کولې، نو ناڅاپه يوه د اور جنګى ګاډۍ چې د اور آسونو راښکله د هغوئ مينځ ته راغله او يو زورَور باد الياس بره آسمان ته وخېژولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9003, '2 Kings 2:12', '2 Kings', 2, 12, '&nbsp;اليشع دا وليدل او الياس ته يې چغه کړه، ”زما پلاره، زما پلاره. ګوره، د اِسرائيل جنګى ګاډو او په دې سوارو کسانو زما نېک يوړو.“ او چې څنګه هغه د نظر نه پناه شو، نو اليشع د غم نه خپلې جامې وشلولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9004, '2 Kings 2:13', '2 Kings', 2, 13, '&nbsp;بيا هغۀ د الياس هغه چُوغه راواخستله چې کومه د الياس نه غورزېدلې وه او واپس لاړو او د اُردن په غاړه باندې ودرېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9005, '2 Kings 2:14', '2 Kings', 2, 14, '&nbsp;هغۀ د الياس په چُوغه باندې اوبۀ ووهلې او وې فرمائيل، ”مالِک خُدائ، د الياس خُدائ پاک چرته دے؟“ نو هغۀ اوبۀ بيا ووهلې او اوبۀ تقسيم شوې او هغه بل خوا پورې وتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9006, '2 Kings 2:15', '2 Kings', 2, 15, '&nbsp;د يريحو پنځوسو پېغمبرانو هغه وليدو او ورته يې وفرمائيل، ”د الياس روح د اليشع سره دے.“ هغوئ د هغۀ سره مِلاوېدو له لاړل، د هغۀ په مخکښې زمکې ته د عزت نه ټيټ شول', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9007, '2 Kings 2:16', '2 Kings', 2, 16, '&nbsp;او ورته يې ووئيل، ”دلته مونږ پنځوس سړى يُو چې ټول تکړه يُو. راځئ چې لاړ شُو او ستا نېک ولټوُو. کېدے شى چې د مالِک خُدائ روح هغه وړے وى او چرته په غر يا وادۍ کښې يې پرېښے وى.“ اليشع ورته وفرمائيل، ”تاسو به نۀ ځئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9008, '2 Kings 2:17', '2 Kings', 2, 17, '&nbsp;خو هغوئ بيا بيا ووئيل نو هغۀ پرېښودل چې لاړ شى. هغه پنځوسو کسانو درې ورځې لټون وکړو خو هغه يې ونۀ موندلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9009, '2 Kings 2:18', '2 Kings', 2, 18, '&nbsp;کله چې هغوئ راواپس شول نو اليشع تر اوسه پورې په يريحو کښې وو. اليشع ترې نه تپوس وکړو، ”ما تاسو ته وئيلى نۀ وُو څۀ چې مۀ ځئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9010, '2 Kings 2:19', '2 Kings', 2, 19, '&nbsp;د يريحو څۀ سړى اليشع له لاړل او ورته يې ووئيل، ”صاحِبه، تا ته پته ده چې دا يو ښۀ ښار دے، خو اوبۀ يې ښې نۀ دى او زمکه يې شاړه ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9011, '2 Kings 2:20', '2 Kings', 2, 20, '&nbsp;نو هغۀ حُکم وکړو چې، ”په يو نوى لوښى کښې لږه مالګه واچوئ او ما له يې راوړئ.“ نو هغوئ ورله مالګه راوړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9012, '2 Kings 2:21', '2 Kings', 2, 21, '&nbsp;او هغه چينې ته لاړو او مالګه يې په اوبو کښې واچوله او وې فرمائيل، ”مالِک خُدائ داسې فرمائى، زۀ دا اوبۀ صفا کوم، نو نور څوک به نۀ مرى او زمکه به شاړه نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9013, '2 Kings 2:22', '2 Kings', 2, 22, '&nbsp;او هغه اوبۀ تر اوسه پورې صفا دى، لکه څنګه چې اليشع فرمائيلى وُو چې داسې به وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9014, '2 Kings 2:23', '2 Kings', 2, 23, '&nbsp;اليشع د يريحو نه روان شو چې بيت‌ايل ته لاړ شى او په لار کښې څۀ هلکان د ښار نه راووتل او په هغۀ پورې يې ټوقې کولې. هغوئ چغې وهلې، ”د دې ځائ نه لاړ شه ګنجيه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9015, '2 Kings 2:24', '2 Kings', 2, 24, '&nbsp;اليشع راوګرځېدو، هلکانو ته يې وکتل او د مالِک خُدائ په نوم يې په هغوئ لعنت ووئيلو. نو د ځنګل نه دوه مېلوګانې راووتلې او دوه څلوېښت هلکان يې ټوټې ټوټې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9016, '2 Kings 2:25', '2 Kings', 2, 25, '&nbsp;اليشع د کرمل غر ته روان وو او وروستو سامريه ته راواپس شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9017, '2 Kings 3:1', '2 Kings', 3, 1, '&nbsp;نو د يهوداه بادشاه يهوسفط د بادشاهۍ په اتلسم کال، د اخى‌اب زوئ يورام د اِسرائيل بادشاه شو او په سامريه باندې يې دولس کاله بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9018, '2 Kings 3:2', '2 Kings', 3, 2, '&nbsp;هغۀ د مالِک خُدائ خِلاف ګناه کړې وه، خو د خپل پلار يا د خپلې مور ايزبل په شان خراب نۀ وو او د بعل هغه بُت يې راوغورزولو کوم چې د هغۀ پلار جوړ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9019, '2 Kings 3:3', '2 Kings', 3, 3, '&nbsp;خو يورام د نباط زوئ يربعام په شان ګناه کوله. يورام اِسرائيليان د ګناه طرف ته بوتلل او دا ګناه يې نۀ پرېښودله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9020, '2 Kings 3:4', '2 Kings', 3, 4, '&nbsp;د موآب بادشاه ميسا به ګډې ساتلې او هر کال يې سل زره ګډُورى او د سلو زرو ګډو وړۍ د اِسرائيل بادشاه له په محصُول کښې ورکولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9021, '2 Kings 3:5', '2 Kings', 3, 5, '&nbsp;خو چې د اِسرائيل بادشاه اخى‌اب مړ شو، نو ميسا د اِسرائيل خِلاف بغاوت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9022, '2 Kings 3:6', '2 Kings', 3, 6, '&nbsp;نو يورام سمدستى د سامريه نه لاړو او خپل ټول فوجيان يې راغونډ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9023, '2 Kings 3:7', '2 Kings', 3, 7, '&nbsp;هغۀ د يهوداه بادشاه يهوسفط له دا پېغام ولېږلو، ”د موآب بادشاه زما خِلاف بغاوت کړے دے، تۀ به د هغۀ خِلاف په جنګ کښې زما ملګرتيا کوې څۀ؟“ يهوسفط بادشاه ورته په جواب کښې ووئيل، ”زۀ به ستا ملګرتيا وکړم، زما سړى، آسونه او زۀ ستا د حُکم لاندې يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9024, '2 Kings 3:8', '2 Kings', 3, 8, '&nbsp;خو د حملې دپاره به په کومه لار ځُو؟“ يورام ورته ووئيل، ”مونږ به د ادوم په صحرا کښې په اوږده لار باندې لاړ شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9025, '2 Kings 3:9', '2 Kings', 3, 9, '&nbsp;نو يورام بادشاه او د يهوداه او ادوم بادشاهان روان شول. د اوو ورځو د مزل نه پس، د هغوئ سره اوبۀ ختمې شوې او د سړو او د ځناورو دپاره لږې هم پاتې نۀ شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9026, '2 Kings 3:10', '2 Kings', 3, 10, '&nbsp;يورام بادشاه په خفګان کښې ووئيل، ”افسوس، مالِک خُدائ مونږ درې واړه دلته د دې دپاره راوستى يُو چې موآبيانو ته مو حواله کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9027, '2 Kings 3:11', '2 Kings', 3, 11, '&nbsp;يهوسفط تپوس وکړو، ”دلته داسې پېغمبر نشته څۀ چې د هغۀ په ذريعه مونږ د مالِک خُدائ نه تپوس وکړُو؟“ نو د يورام بادشاه د فوج يو آفسر ورته ووئيل، ”د سافط زوئ اليشع دلته شته. هغه د الياس مددګار وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9028, '2 Kings 3:12', '2 Kings', 3, 12, '&nbsp;يهوسفط بادشاه ووئيل، ”مالِک خُدائ د هغۀ په ذريعه کلام کوى.“ نو هغه درې بادشاهان اليشع له لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9029, '2 Kings 3:13', '2 Kings', 3, 13, '&nbsp;اليشع د اِسرائيل بادشاه ته وفرمائيل، ”زۀ په تا باندې څۀ وکړم، هغه پېغمبرانو له لاړ شه چې ستا مور او پلار ورسره مشوره کوله.“ خو يورام ورته ووئيل، ”نه، ځکه چې دا مالِک خُدائ وو چې مونږ درې بادشاهان يې راغونډ کړُو چې موآبيانو ته مو حواله کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9030, '2 Kings 3:14', '2 Kings', 3, 14, '&nbsp;اليشع ورته وفرمائيل، ”زۀ د هغه ژوندى ربُ الافواج په نوم قسم کوم د چا چې زۀ خِدمت کوم، کۀ ما ستاسو د ملګرى د يهوداه بادشاه يهوسفط عزت نۀ کولے نو ما به ستاسو دپاره هيڅ هم نۀ وُو کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9031, '2 Kings 3:15', '2 Kings', 3, 15, '&nbsp;اوس ما له د موسيقۍ والا راوله.“ نو کله چې هغۀ موسيقى وغږوله، نو مالِک خُدائ په اليشع باندې وحى نازله کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9032, '2 Kings 3:16', '2 Kings', 3, 16, '&nbsp;او اليشع وفرمائيل، ”مالِک خُدائ داسې فرمائى، دا اوچه وادى به د اوبو د ډنډونو نه ډکه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9033, '2 Kings 3:17', '2 Kings', 3, 17, '&nbsp;تاسو به هيڅ باران يا هوا ونۀ وينئ، خو دا نِهر به بيا هم د اوبو نه ډک شى او تاسو، ستاسو څاروى او نور ځناور به اوبۀ وڅښى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9034, '2 Kings 3:18', '2 Kings', 3, 18, '&nbsp;خو دا کار کول د مالِک خُدائ دپاره آسان دے، هغه به تاسو له په موآبيانو باندې فتح هم درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9035, '2 Kings 3:19', '2 Kings', 3, 19, '&nbsp;تاسو به د هغوئ د پَخو دېوالونو والا ټول ښائسته ښارونه فتح کړئ، تاسو به ټولې ښې ونې راوغورزوئ، ټولې چينې به بندې کړئ او د هغوئ ټول آباد پټى به تباه کړئ او په کاڼو به يې پټ کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9036, '2 Kings 3:20', '2 Kings', 3, 20, '&nbsp;په ورپسې سحر، د سحر د نذرانې په وخت، د ادوم د طرف نه اوبۀ راوبهېدلې او مُلک د اوبو نه ډک شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9037, '2 Kings 3:21', '2 Kings', 3, 21, '&nbsp;کله چې موآبيان خبر شول چې هغه درې بادشاهان په هغوئ باندې د حملې دپاره راغلى دى، نو هغه ټول بوډاګان او ځوانان سړى راوغوښتے شول چا چې جنګ کولے شو او هغوئ د حد په پوله باندې د جنګ دپاره ودرولے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9038, '2 Kings 3:22', '2 Kings', 3, 22, '&nbsp;په ورپسې سحر چې هغوئ پاڅېدل، نو نمر په اوبو باندې ځلېدو او اوبۀ د وينو په شان سرې ښکارېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9039, '2 Kings 3:23', '2 Kings', 3, 23, '&nbsp;هغوئ په حېرانتيا سره ووئيل، ”ګورئ، دا خو وينه ده، هغه درې لښکرو به د يو بل سره جنګ کړے وى او ټول به مړۀ شوى وى. راځئ چې مالِ غنيمت راغونډ کړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9040, '2 Kings 3:24', '2 Kings', 3, 24, '&nbsp;خو چې کله هغوئ خېمو ته ورسېدل، نو اِسرائيل ورباندې حمله وکړه او واپس يې وشړل. اِسرائيليان د موآب مُلک پورې په هغوئ پسې وُو او په تلو تلو کښې يې هغوئ وژل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9041, '2 Kings 3:25', '2 Kings', 3, 25, '&nbsp;او د هغوئ ښارونه يې تباه کول. کله چې هغوئ د آباد پټى نه تېرېدل، نو هر يو اِسرائيلى به يو کاڼے وراچولو چې په کاڼو به پټ شو، هغوئ ټولې چينې هم بندې کړې او ټولې ښې ونې يې راوغورزولې. په آخر کښې صِرف د قير‌حراست شاهى ښار پاتې شو او چې د کومو سړو سره ليندې وې نو هغوئ دا ښار محاصره کړو او حمله يې ورباندې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9042, '2 Kings 3:26', '2 Kings', 3, 26, '&nbsp;کله چې د موآب بادشاه ته پته ولګېده چې جنګ بائيلى، نو هغۀ خپل اووۀ سوه د تُورو والا فوجيان د ځان سره کړل او د دشمن په صفونو کښې يې د ځان دپاره د لارې جوړولو کوشش وکړو چې د شام بادشاه له وتښتى، خو هغه ناکامه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9043, '2 Kings 3:27', '2 Kings', 3, 27, '&nbsp;نو هغۀ خپل مشر زوئ د ځان سره بوتلو چې کوم د هغۀ نه پس بادشاه جوړېدو او هغه يې په دېوال باندې د سوزېدونکې نذرانې په توګه پېش کړو. نو په اِسرائيل سخت قهر نازل شو او هغوئ د ښار نه راوګرځېدل او خپل مُلک ته راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9044, '2 Kings 4:1', '2 Kings', 4, 1, '&nbsp;د پېغمبرانو د يوې ډلې د يو پېغمبر کونډه اليشع له لاړه او ورته يې ووئيل، ”صاحِبه، زما خاوند مړ دے. لکه څنګه چې تا ته پته ده چې هغه د مالِک خُدائ نه يرېدو، نو ما له قرض‌خوا راغلے دے چې زما دوه زامن بوځى او خپل غلامان يې جوړ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9045, '2 Kings 4:2', '2 Kings', 4, 2, '&nbsp;هغۀ ترې نه تپوس وکړو، ”زۀ ستا دپاره څۀ وکړم؟ ما ته ووايه چې ستا په کور کښې څۀ شته؟“ هغې ورته ووئيل، ”د زيتُونو تېلو د يو وړوکى لوښى نه بغېر هيڅ هم نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9046, '2 Kings 4:3', '2 Kings', 4, 3, '&nbsp;اليشع هغې ته وفرمائيل، ”خپلو ټولو ګاونډيانو کره لاړه شه او چې څومره ډېر کېدے شى د هغوئ نه خالى لوښى وغواړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9047, '2 Kings 4:4', '2 Kings', 4, 4, '&nbsp;بيا تۀ او ستا زامن کور ته لاړ شئ، دروازه بنده کړئ او په لوښو کښې تېل اچول شروع کړئ. چې يو لوښے ډکيږى نو هغه يو طرف ته اېږدئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9048, '2 Kings 4:5', '2 Kings', 4, 5, '&nbsp;نو هغه ښځه خپلو زامنو سره کور ته دننه لاړه، دروازه يې بنده کړه، د زيتُونو هغه وړوکے لوښے يې واخستلو او تېل يې په لوښو کښې اچول او د هغې زامنو ورله لوښى راوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9049, '2 Kings 4:6', '2 Kings', 4, 6, '&nbsp;کله چې هغوئ ټول لوښى ډک کړل، نو هغې ترې نه تپوس وکړو چې نور شته. نو يو زوئ ورته ووئيل، ”نور نشته.“ نو د تېلو بهېدل بند شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9050, '2 Kings 4:7', '2 Kings', 4, 7, '&nbsp;هغه واپس اليشع پېغمبر له لاړه او هغۀ ورته وفرمائيل، ”د زيتُونو تېل خرڅ کړه او خپل ټول قرض ختم کړه او چې پېسې پاتې شى نو په هغې باندې تۀ او ستا زامن خپله خرچه کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9051, '2 Kings 4:8', '2 Kings', 4, 8, '&nbsp;يوه ورځ اليشع شونيم ته لاړو، چرته چې يوه مالداره ښځه اوسېده. هغې هغۀ له د روټۍ دعوت ورکړو، بيا چې هغه کله هم شونيم ته تلو نو د هغې په کور کښې به يې روټۍ خوړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9052, '2 Kings 4:9', '2 Kings', 4, 9, '&nbsp;هغې خپل خاوند ته ووئيل، ”دلته چې کوم سړے اکثر راځى نو زما دا يقين دے چې هغه د خُدائ پاک خِدمتګار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9053, '2 Kings 4:10', '2 Kings', 4, 10, '&nbsp;راځه چې په چت باندې يوه وړه کوټه جوړه کړُو، يو کټ، مېز، کُرسۍ او يوه ډيوه به په کښې کېږدو او چې هغه کله مونږ له راځى نو هلته به پاتې کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9054, '2 Kings 4:11', '2 Kings', 4, 11, '&nbsp;يوه ورځ هغه راغلو او د آرام دپاره خپلې کوټې ته وختلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9055, '2 Kings 4:12', '2 Kings', 4, 12, '&nbsp;نو هغۀ خپل نوکر جيحازى ته وفرمائيل چې، ”لاړ شه او هغه شونيمى ښځه راوغواړه.“ کله چې هغه راغله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9056, '2 Kings 4:13', '2 Kings', 4, 13, '&nbsp;نو هغۀ جيحازى ته وفرمائيل، ”هغې ته ووايه چې زمونږ د ضرورتونو پوره کولو دپاره يې کوم تکليف کړے دے نو د دې په بدل کښې زۀ د هغې دپاره څۀ وکړم. کېدے شى چې هغه ما ته ووائى چې بادشاه يا د فوج مشر له لاړ شم او د هغې سفارش وکړم.“ هغې ورته ووئيل، ”زما خلق زما خيال ساتى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9057, '2 Kings 4:14', '2 Kings', 4, 14, '&nbsp;اليشع د جيحازى نه تپوس وکړو، ”نو زۀ د هغې دپاره څۀ وکړم؟“ هغۀ ورته ووئيل، ”خبره دا ده چې د هغې بچى نشته او د هغې خاوند يو بوډا سړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9058, '2 Kings 4:15', '2 Kings', 4, 15, '&nbsp;اليشع حُکم وکړو، ”هغې ته ووايه چې دلته راشى.“ نو هغه راغله او د دروازې په خولۀ کښې ودرېدله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9059, '2 Kings 4:16', '2 Kings', 4, 16, '&nbsp;اليشع هغې ته وفرمائيل، ”په راتلونکى کال کښې هم په دې وخت کښې به تا په خپل غېږ کښې يو زوئ نيولے وى.“ هغې ووئيل، ”صاحِبه، ما ته دروغ مۀ وايه. تۀ د خُدائ پاک خِدمتګار يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9060, '2 Kings 4:17', '2 Kings', 4, 17, '&nbsp;خو لکه چې څنګه اليشع فرمائيلى وُو، په ورپسې کال تقريباً هم هغه وخت د هغې يو زوئ پېدا شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9061, '2 Kings 4:18', '2 Kings', 4, 18, '&nbsp;کله چې هلک لوئ شو نو يوه ورځ هغه بهر خپل پلار له ووتلو، پلار يې د لَوګرو سره په پټى کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9062, '2 Kings 4:19', '2 Kings', 4, 19, '&nbsp;ناڅاپه هغۀ خپل پلار ته چغه کړه، ”زما په سر څۀ وشول. زما سر خوږيږى.“ پلار يې يو نوکر ته ووئيل، ”هلک خپلې مور له بوځه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9063, '2 Kings 4:20', '2 Kings', 4, 20, '&nbsp;هغه نوکر هلک واپس خپلې مور له بوتلو، او تر هغې پورې يې په غېږ کښې نيولے وو، چې د غرمې په وخت هغه مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9064, '2 Kings 4:21', '2 Kings', 4, 21, '&nbsp;هغې هغه د اليشع کوټې له يوړو، هغه يې په کټ کښې واچولو او لاړه، دروازه يې ورپسې بنده کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9065, '2 Kings 4:22', '2 Kings', 4, 22, '&nbsp;بيا يې خپل خاوند راوغوښتلو او ورته يې ووئيل، ”يو نوکر د خر سره دلته راولېږه چې زۀ زر زر د خُدائ پاک خِدمتګار له لاړه شم او بيا واپس راشم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9066, '2 Kings 4:23', '2 Kings', 4, 23, '&nbsp;خاوند ترې نه تپوس وکړو، ”تۀ نن ولې روانه شوې؟ نن خو نۀ د سبت ورځ ده او نۀ د نوې مياشتې اختر دے.“ هغې ورته ووئيل، ”خېر به شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9067, '2 Kings 4:24', '2 Kings', 4, 24, '&nbsp;بيا هغې خر کته کړو او نوکر له يې حُکم ورکړو، ”څومره تېز چې خر تلے شى نو بو يې ځه او چې ما درته وئيلى نۀ وى نو چې په مزه يې نۀ کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9068, '2 Kings 4:25', '2 Kings', 4, 25, '&nbsp;نو هغه روانه شوه او د کرمل غر ته لاړه، چرته چې اليشع وو. اليشع هغه د لرې ځائ نه وليده چې راروانه وه او خپل نوکر جيحازى ته يې وفرمائيل، ”ګوره، هغه ښځه د شونيم نه راغله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9069, '2 Kings 4:26', '2 Kings', 4, 26, '&nbsp;هغې له تېز ورشه او دا معلوم کړه چې هغه، د هغې خاوند، د هغې زوئ په خېر دى.“ هغه ښځې جيحازى ته ووئيل، ”آو، هر څۀ په خير دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9070, '2 Kings 4:27', '2 Kings', 4, 27, '&nbsp;خو چې کله هغه په غرۀ باندې اليشع له راغله نو هغه د اليشع په مخکښې ټيټه شوه او هغۀ ته په پښو پرېوته. جيحازى هغې له ديکه ورکوله چې اليشع ورته وفرمائيل، ”هغه پرېږده، تۀ دا نۀ ګورې چې ډېره زياته خفه ده؟ او مالِک خُدائ ما ته نۀ دى وئيلى چې څۀ شوى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9071, '2 Kings 4:28', '2 Kings', 4, 28, '&nbsp;ښځې هغۀ ته ووئيل، ”صاحِبه، ما ستا نه زوئ غوښتے وو څۀ؟ ما تا ته نۀ وُو وئيلى چې زما اُميدونه مۀ راپاڅوه؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9072, '2 Kings 4:29', '2 Kings', 4, 29, '&nbsp;اليشع جيحازى له مخ راوړولو او ورته يې وفرمائيل، ”ځان تيار کړه، زما امسا واخله او لاړ شه. په لاره باندې د چا سره سلام دُعا مۀ کوه او کۀ په تا څوک سلام اچوى نو جواب هم مۀ ورکوه. هغه کور ته سيدها لاړ شه او زما امسا د هلک په مخ باندې کېږده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9073, '2 Kings 4:30', '2 Kings', 4, 30, '&nbsp;د هلک مور اليشع ته ووئيل، ”زما دې په ژوندى مالِک خُدائ او ستا په سر قسم وى چې زۀ به ستا نه بغېر لاړه نۀ شم.“ نو اليشع د هغې سره لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9074, '2 Kings 4:31', '2 Kings', 4, 31, '&nbsp;جيحازى وړاندې لاړو او د هلک په مخ يې امسا کېښوده، خو هيڅ آواز يا د ژوند څۀ علامت په کښې نۀ وو. نو هغه د اليشع سره مِلاوېدو دپاره واپس لاړو او ورته يې ووئيل، ”هغه هلک خو پا نۀ څېدو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9075, '2 Kings 4:32', '2 Kings', 4, 32, '&nbsp;کله چې اليشع ور ورسېدو، نو هغه کوټې ته يواځې دننه لاړو او وې ليدل چې هلک په کټ باندې مړ پروت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9076, '2 Kings 4:33', '2 Kings', 4, 33, '&nbsp;هغۀ دروازه بنده کړه او مالِک خُدائ ته يې سوال وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9077, '2 Kings 4:34', '2 Kings', 4, 34, '&nbsp;بيا هغه کټ له لاړو او په هلک ورپرېوتلو، خپله خولۀ يې د هلک په خولۀ کېښوده، سترګې د هغۀ په سترګو او لاسونه يې د هلک په لاسونو کېښودل. بيا هغه د هلک د پاڅه څملاستو، نو هلک ګرمېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9078, '2 Kings 4:35', '2 Kings', 4, 35, '&nbsp;اليشع پاڅېدو، په کوټه کښې وګرځېدو او واپس لاړو او په هلک باندې څملاستو. هلک اووۀ ځل انټوشى وکړو او بيا يې سترګې وغړولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9079, '2 Kings 4:36', '2 Kings', 4, 36, '&nbsp;اليشع جيحازى راوغوښتلو او ورته يې وفرمائيل چې، ”د هلک مور راوغواړه.“ کله چې هغه راغله، نو هغۀ ورته وفرمائيل، ”زوئ دې واخله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9080, '2 Kings 4:37', '2 Kings', 4, 37, '&nbsp;نو هغه د اليشع په پښو پرېوتله، زمکې ته ټيټه شوه، او بيا هغې خپل زوئ واخستلو او لاړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9081, '2 Kings 4:38', '2 Kings', 4, 38, '&nbsp;کله چې اليشع جِلجال ته راواپس شو، نو په هغه مُلک کښې قحط وو. د پېغمبرانو يوه ډله د هغۀ په وړاندې ناسته وه، هغۀ خپل نوکر ته وفرمائيل چې په اور باندې يو غټ لوښے کېږده او د هغوئ دپاره ښوروا تياره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9082, '2 Kings 4:39', '2 Kings', 4, 39, '&nbsp;د هغوئ نه يو کس پټو ته لاړو چې څۀ بوټى راټول کړى. هغۀ د ځنګلى کدو يو بوټے وموندلو او د ځنګلى کدوانو نه يې يوه غېږه راټوله کړه. هغۀ دا راوړل، پرې يې کړل او په ښوروا کښې يې واچول، خو په دې نۀ پوهېدو چې دا څۀ شے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9083, '2 Kings 4:40', '2 Kings', 4, 40, '&nbsp;ښوروا هغه سړو ته واچولے شوه چې وې خورى، خو چې څنګه يې دا وڅَکله نو هغوئ اليشع ته وفرمائيل، ”اے د خُدائ پاک خِدمتګاره. په دې لوښى کښې خو زهر دى.“ او هغوئ دا نۀ شوه خوړلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9084, '2 Kings 4:41', '2 Kings', 4, 41, '&nbsp;اليشع څۀ اوړۀ راوغوښتل، لوښى کښې يې واچول او وې فرمائيل، ”هغوئ ته لږه نوره ښوروا واچوه.“ نو په لوښى کښې ښوروا ټيک شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9085, '2 Kings 4:42', '2 Kings', 4, 42, '&nbsp;يو بل ځل، د بعل‌سليسه نه يو سړے راغلو، اليشع له يې شل روټۍ راوړې چې په هغه کال د اوربشو د اول فصل نه تيارې شوې وې او څۀ تازه وَږى يې هم راوړل. اليشع خپل نوکر ته وفرمائيل چې، ”د پېغمبرانو قبيلې له دا خوراک ورکړه،“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9086, '2 Kings 4:43', '2 Kings', 4, 43, '&nbsp;خو هغۀ ورته وفرمائيل، ”سلو سړو ته دا خوراک څنګه کېږدم؟“ اليشع ورته وفرمائيل، ”هغوئ له يې ورکړه چې وې خورى، ځکه چې مالِک خُدائ فرمائى چې هغوئ به ورباندې ماړۀ شى او ترې نه پاتې به هم شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9087, '2 Kings 4:44', '2 Kings', 4, 44, '&nbsp;نو نوکر روټۍ د هغوئ په مخکښې کېښوده او لکه چې څنګه مالِک خُدائ فرمائيلى وُو، هغوئ ټولو روټۍ وخوړه او څۀ ترې نه پاتې هم شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9088, '2 Kings 5:1', '2 Kings', 5, 1, '&nbsp;نو د شامى فوج مشر نعمان، د شام د بادشاه يو ډېر عزتمند کس وو، ځکه چې د نعمان په ذريعه مالِک خُدائ شامى فوج له فتح ورکړې وه. هغه يو تکړه فوجى وو، خو د جذام بيمارى يې لرله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9089, '2 Kings 5:2', '2 Kings', 5, 2, '&nbsp;د اِسرائيل خِلاف په يوه حمله کښې، شاميانو يوه وړه اِسرائيلى جينۍ بوتله، چې هغه د نعمان د ښځې نوکره شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9090, '2 Kings 5:3', '2 Kings', 5, 3, '&nbsp;يوه ورځ هغې خپلې نېکې ته ووئيل، ”زما خواهش دے چې زما نېک هغه سامرى پېغمبر له لاړ شى. نو د هغۀ په ذريعه به زما نېک د جذام نه روغ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9091, '2 Kings 5:4', '2 Kings', 5, 4, '&nbsp;کله چې نعمان دا واورېدل، نو هغه بادشاه له لاړو او چې جينۍ څۀ وئيلى وُو هغه يې ورته ووئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9092, '2 Kings 5:5', '2 Kings', 5, 5, '&nbsp;بادشاه ورته ووئيل، ”د اِسرائيل بادشاه له لاړ شه او دا خط هغۀ له يوسه.“ نو نعمان روان شو او د سپينو زرو دېرش زره سيکې، شپږ زره د سرو زرو سيکې او لس جوړه ښې جامې يې يوړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9093, '2 Kings 5:6', '2 Kings', 5, 6, '&nbsp;هغۀ چې کوم خط د اِسرائيل بادشاه له وړے وو په هغې کښې وئيلے شوى وُو، ”کله چې دا خط درورسى نو تۀ به زما آفسر نعمان وپېژنې. زۀ غواړم چې تۀ د هغۀ د جذام علاج وکړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9094, '2 Kings 5:7', '2 Kings', 5, 7, '&nbsp;کله چې د اِسرائيل بادشاه دا خط وکتلو، نو هغۀ د يرې نه خپلې جامې وشلولې او وې وئيل، ”د شام د بادشاه دا خيال دے چې زۀ دا جذامى سړے روغ کړم؟ ولې زۀ خُدائ پاک يم، چې ژوندى کول او مړۀ کول کوم؟ هغه په دې کوشش کښې دے چې ما سره جنګ شروع کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9095, '2 Kings 5:8', '2 Kings', 5, 8, '&nbsp;کله چې اليشع پېغمبر د دې نه خبر شو، نو هغۀ بادشاه له دا خبر ورولېږلو، ”تۀ ولې خفه يې؟ هغه سړے ما له راولېږه، نو هغۀ ته به پته ولګى چې په اِسرائيل کښې پېغمبر شته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9096, '2 Kings 5:9', '2 Kings', 5, 9, '&nbsp;نو نعمان د خپلو آسونو او جنګى ګاډو سره لاړو او د اليشع د کور د دروازې په خولۀ کښې ودرېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9097, '2 Kings 5:10', '2 Kings', 5, 10, '&nbsp;اليشع يو نوکر بهر ورولېږلو چې هغۀ ته ووائى چې، ”لاړ شه او خپل ځان د اُردن په سيند کښې اووۀ ځل ووينځه، نو ستا څرمن به بيا ښۀ شى او تۀ به د جذام نه روغ شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9098, '2 Kings 5:11', '2 Kings', 5, 11, '&nbsp;خو نعمان غصه شو او لاړو او وې وئيل، ”زما خيال دا وو چې هغه به خامخا ما له راوځى، مالِک خُدائ خپل خُدائ پاک ته به سوال وکړى او زما د بيمارې څرمنې دپاسه به خپل لاس ونيسى او زۀ به روغ شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9099, '2 Kings 5:12', '2 Kings', 5, 12, '&nbsp;په دمشق کښې د ابانه او فرفر سيندونه په اِسرائيل کښې د ټولو سيندونو نه ښۀ نۀ دى څۀ؟ ما په هغه سيندونو کښې خپل ځان نۀ شو وينځلے چې روغ شوے وے.“ نو هغه راواپس شو او په غصه کښې لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9100, '2 Kings 5:13', '2 Kings', 5, 13, '&nbsp;د هغۀ نوکران ورغلل او ورته يې ووئيل، ”صاحِبه، کۀ تا ته پېغمبر فرمائيلى وے چې څۀ غټ کار وکړه، نو تا به نۀ وو کړے څۀ؟ لکه څنګه چې هغۀ درته وفرمائيل نو تۀ خپل ځان ولې نۀ وينځې چې روغ شې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');